def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = [0, 0]  # stems above, stems below

    for r in range(h):
        for c in range(1, w - 1):
            if grid[r][c - 1] == grid[r][c] == grid[r][c + 1] == 2:
                if r > 0 and grid[r - 1][c] == 2:
                    counts[0] += 1
                if r + 1 < h and grid[r + 1][c] == 2:
                    counts[1] += 1

    out = [[0] * 6 for _ in range(3)]
    slots = [(0, 0), (2, 0), (0, 2), (2, 2)]
    for i in range(min(counts[0], 4)):
        r, c = slots[i]
        out[r][c] = 3
    for i in range(min(counts[1], 4)):
        r, c = slots[i]
        out[r][c + 3] = 1
    return out
